'use client'

import { useState, useEffect } from 'react'

const tools = ['Cursor', 'Codex', 'Claude Code']

export default function Header() {
  const [toolIndex, setToolIndex] = useState(0)
  const [displayText, setDisplayText] = useState('')
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    const currentTool = tools[toolIndex]

    const timeout = setTimeout(() => {
      if (!isDeleting) {
        if (displayText.length < currentTool.length) {
          setDisplayText(currentTool.slice(0, displayText.length + 1))
        } else {
          setTimeout(() => setIsDeleting(true), 2000)
        }
      } else {
        if (displayText.length > 0) {
          setDisplayText(displayText.slice(0, -1))
        } else {
          setIsDeleting(false)
          setToolIndex((prev) => (prev + 1) % tools.length)
        }
      }
    }, isDeleting ? 50 : 100)

    return () => clearTimeout(timeout)
  }, [displayText, isDeleting, toolIndex])

  return (
    <div className="w-full flex flex-col items-center justify-center text-center space-y-4 fade-in-up">
      {/* Logo */}
      <div className="flex items-center justify-center">
        <span className="text-5xl font-semibold text-primary tracking-tight">
          slait
        </span>
        <span className="ml-2 w-[8px] h-9 bg-primary animate-cursor-blink" />
      </div>

      {/* Terminal prompt indicator */}
      <div className="text-sm font-mono text-primary/70">
        $ slait analyze --session <span className="text-primary/50 animate-pulse">[awaiting file]</span>
      </div>

      {/* Rotating tool text */}
      <p className="text-xl font-mono text-foreground">
        Analyze your sessions with{' '}
        <span className="text-primary scan-glow">{displayText}</span>
        <span className="inline-block w-[2px] h-5 bg-primary ml-0.5 align-middle animate-cursor-blink" />
      </p>
    </div>
  )
}

