const tools = ['Cursor', 'Codex', 'Claude Code']

interface UploadZoneProps {
  isAnalyzing: boolean
  setIsAnalyzing: (value: boolean) => void
  onAnalysisComplete: (analysis: AIUsageAnalysis) => void
}

export default function UploadZone({ isAnalyzing, setIsAnalyzing, onAnalysisComplete }: UploadZoneProps) {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [fileName, setFileName] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [toolIndex, setToolIndex] = useState(0)
  const [displayText, setDisplayText] = useState('')
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    const currentTool = tools[toolIndex]

    const timeout = setTimeout(() => {
      if (!isDeleting) {
        if (displayText.length < currentTool.length) {
          setDisplayText(currentTool.slice(0, displayText.length + 1))
        } else {
          setTimeout(() => setIsDeleting(true), 2000)
        }
      } else {
        if (displayText.length > 0) {
          setDisplayText(displayText.slice(0, -1))
        } else {
          setIsDeleting(false)
          setToolIndex((prev) => (prev + 1) % tools.length)
        }
      }
    }, isDeleting ? 50 : 100)

    return () => clearTimeout(timeout)
  }, [displayText, isDeleting, toolIndex])

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)

    const files = e.dataTransfer.files
    if (files && files.length > 0) {
      handleFile(files[0])
    }
  }

  const handleFile = async (file: File) => {
    setFileName(file.name)
    setError(null)
    setIsAnalyzing(true)

    try {
      // Read the file content
      const content = await file.text()

      // Call the API
      const response = await fetch('/api/analyze', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ chatLog: content }),
      })

      if (!response.ok) {
        throw new Error('Failed to analyze chat log')
      }

      const analysis: AIUsageAnalysis = await response.json()
      onAnalysisComplete(analysis)
    } catch (err) {
      console.error('Error analyzing file:', err)
      setError(err instanceof Error ? err.message : 'An error occurred')
    } finally {
      setIsAnalyzing(false)
    }
  }

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.currentTarget.files
    if (files && files.length > 0) {
      handleFile(files[0])
    }
  }

  const handleClick = () => {
    fileInputRef.current?.click()
  }

  return (
